        int parcelas = request.getParcelas() != null ? request.getParcelas() : 1;

        validarParcelamento(formaPagamento, parcelas);

        BigDecimal frete = calcularFrete(modalidade, pesoTotal, nivelClube);

        BigDecimal descontoCupom = cupom != null
